/** PersistentVolumeSpec is the specification of a persistent volume. */
export interface PersistentVolumeSpec {
    /**
     * capacity is the description of the persistent volume's resources and capacity.
     * More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes#capacity
     * +optional
     */
    capacity: { [key: string]: Quantity };
    /** persistentVolumeSource is the actual volume backing the persistent volume. */
    persistentVolumeSource?: PersistentVolumeSource | undefined;
    /**
     * accessModes contains all ways the volume can be mounted.
     * More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes#access-modes
     * +optional
     * +listType=atomic
     */
    accessModes: string[];
    /**
     * claimRef is part of a bi-directional binding between PersistentVolume and PersistentVolumeClaim.
     * Expected to be non-nil when bound.
     * claim.VolumeName is the authoritative bind between PV and PVC.
     * More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes#binding
     * +optional
     * +structType=granular
     */
    claimRef?: ObjectReference | undefined;
    /**
     * persistentVolumeReclaimPolicy defines what happens to a persistent volume when released from its claim.
     * Valid options are Retain (default for manually created PersistentVolumes), Delete (default
     * for dynamically provisioned PersistentVolumes), and Recycle (deprecated).
     * Recycle must be supported by the volume plugin underlying this PersistentVolume.
     * More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes#reclaiming
     * +optional
     */
    persistentVolumeReclaimPolicy?: string | undefined;
    /**
     * storageClassName is the name of StorageClass to which this persistent volume belongs. Empty value
     * means that this volume does not belong to any StorageClass.
     * +optional
     */
    storageClassName?: string | undefined;
    /**
     * mountOptions is the list of mount options, e.g. ["ro", "soft"]. Not validated - mount will
     * simply fail if one is invalid.
     * More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes/#mount-options
     * +optional
     * +listType=atomic
     */
    mountOptions: string[];
    /**
     * volumeMode defines if a volume is intended to be used with a formatted filesystem
     * or to remain in raw block state. Value of Filesystem is implied when not included in spec.
     * +optional
     */
    volumeMode?: string | undefined;
    /**
     * nodeAffinity defines constraints that limit what nodes this volume can be accessed from.
     * This field influences the scheduling of pods that use this volume.
     * This field is mutable if MutablePVNodeAffinity feature gate is enabled.
     * +optional
     */
    nodeAffinity?: VolumeNodeAffinity | undefined;
    /**
     * Name of VolumeAttributesClass to which this persistent volume belongs. Empty value
     * is not allowed. When this field is not set, it indicates that this volume does not belong to any
     * VolumeAttributesClass. This field is mutable and can be changed by the CSI driver
     * after a volume has been updated successfully to a new class.
     * For an unbound PersistentVolume, the volumeAttributesClassName will be matched with unbound
     * PersistentVolumeClaims during the binding process.
     * +featureGate=VolumeAttributesClass
     * +optional
     */
    volumeAttributesClassName?: string | undefined;
}

